python3 - <<'EOF'
from urllib.parse import urlsplit

for url in ["http://[127.0.0.1:8765/health", "http://127.0.0.1]:8765/health"]:
    print(repr(url))
    try:
        p = urlsplit(url)
        print("  scheme:", p.scheme, "hostname:", p.hostname, "port:", end=" ")
        try:
            print(p.port)
        except Exception as e:
            print(f"port raises {type(e).__name__}: {e}")
    except Exception as e:
        print(f"  urlsplit raises {type(e).__name__}: {e}")
EOF

